    async fn invoke(
        &self,
        request: ModelRequest,
        cancel: CancellationToken,
    ) -> Result<BoxStream<'static, Result<ModelEvent, ModelError>>, ModelError> {
        let prepared = build_body(&self.cfg, &request)?;
        let synthesizing = prepared.synthesizing_output;
        let headers = build_headers(&self.cfg);
        let url = messages_url(&self.cfg);
        let client = self.cfg.http.clone();

        let s = stream! {
            let send_fut = client
                .post(&url)
                .headers(headers)
                .json(&prepared.body)
                .send();

            let response = tokio::select! {
                biased;
                _ = cancel.cancelled() => return,
                r = send_fut => match r {
                    Ok(r) => r,
                    Err(e) => {
                        yield Err(ModelError::Transport(e.to_string()));
                        return;
                    }
                },
            };

            let status = response.status();
            if !status.is_success() {
                let retry_after_ms = parse_retry_after_ms(response.headers());
                let body_bytes = response.bytes().await.unwrap_or_default();
                let parsed: Result<serde_json::Value, _> = serde_json::from_slice(&body_bytes);
                let (ty, message) = parsed
                    .as_ref()
                    .ok()
                    .map(|v| {
                        let ty = v
                            .get("error")
                            .and_then(|e| e.get("type"))
                            .and_then(|t| t.as_str())
                            .unwrap_or("")
                            .to_owned();
                        let msg = v
                            .get("error")
                            .and_then(|e| e.get("message"))
                            .and_then(|m| m.as_str())
                            .unwrap_or("")
                            .to_owned();
                        (ty, msg)
                    })
                    .unwrap_or_else(|| {
                        (
                            String::new(),
                            String::from_utf8_lossy(&body_bytes).into_owned(),
                        )
                    });
                yield Err(map_error_type(Some(status.as_u16()), &ty, &message, retry_after_ms));
                return;
            }

            let mut event_stream = response.bytes_stream().eventsource();
            let mut translator = MessageTranslator::new(synthesizing);

            loop {
                let next = tokio::select! {
                    biased;
                    _ = cancel.cancelled() => return,
                    n = event_stream.next() => n,
                };
                match next {
                    // Stream exhausted normally (clean EOF). Flush a stop
                    // reason buffered by `message_delta` when `message_stop`
                    // never arrived, so the consumer always sees a terminal
                    // event. Deliberately NOT done on the cancellation arm
                    // above or the transport-error arm (below).
                    None => {
                        if let Some(terminal) = translator.finish() {
                            yield terminal;
                        }
                        return;
                    }
                    Some(Err(e)) => {
                        yield Err(ModelError::Transport(e.to_string()));
                        return;
                    }
                    Some(Ok(event)) => {
                        let parsed: AnthropicEvent = match serde_json::from_str(&event.data) {
                            Ok(p) => p,
                            Err(parse_err) => {
                                // Log structured metadata only — the raw payload
                                // may contain user/model/tool content and must
                                // not be written to logs.
                                tracing::warn!(
                                    target: "paigasus::anthropic::sse",
                                    %parse_err,
                                    event_len = event.data.len(),
                                    event_name = %event.event,
                                    "unparseable SSE event payload",
                                );
                                continue;
                            }
                        };
                        match translator.consume(parsed) {
                            Err(e) => {
                                yield Err(e);
                                return;
                            }
                            Ok(events) => {
                                for ev in events {
                                    yield ev;
                                }
                            }
                        }
                    }
                }
            }
        };

        Ok(Box::pin(s))
    }

    fn capabilities(&self) -> ModelCapabilities {
        self.cfg.capabilities
    }

    fn provider(&self) -> &str {
        crate::PROVIDER_ID
    }

    fn model(&self) -> &str {
        &self.cfg.model_id
    }
}

