    assert_eq!(
        provider_data(&events),
        vec![
            (redacted(0, "REDACTED_FAKE_1"), None),
            (redacted(1, "REDACTED_FAKE_2"), None),
            (AnthropicData::Text { index: 2 }, None),
            (
                AnthropicData::ToolUse { index: 3 },
                Some("toolu_01TUKF2PUduQbRPsN2DaUV1u".to_owned())
            ),
        ]
    );
}

